<?php
function report_date($s){$s=(string)$s;$d=DateTime::createFromFormat('!Y-m-d',$s);if(!$d||$d->format('Y-m-d')!==$s)throw new Exception('Choose a valid report date.');return $s;}
function report_filters($input){
 $f=[];foreach(['q','reference','brand','main_category','subcategory','platform','movement','report'] as $k)$f[$k]=trim((string)($input[$k]??''));$f['product_status']=in_array($input['product_status']??'all',['active','inactive','all'],true)?($input['product_status']??'all'):'all';$f['product_id']=max(0,(int)($input['product_id']??0));$f['from']=report_date($input['from']??date('Y-m-01'));$f['to']=report_date($input['to']??date('Y-m-d'));if($f['from']>$f['to'])throw new Exception('From Date must be on or before To Date.');if($f['to']>date('Y-m-d'))throw new Exception('Reports cannot include future dates.');if($f['platform']!==''&&!in_array($f['platform'],['Shopee','Lazada','TikTok'],true))throw new Exception('Invalid platform.');$k=$f['report'];if(in_array($k,['audit','uploads','reversals','closing'],true)){foreach(['brand','main_category','subcategory','movement','reference'] as $x)$f[$x]='';$f['product_id']=0;if($k!=='audit')$f['q']='';if($k!=='uploads')$f['platform']='';}if(in_array($k,['overview','stocks','restricted','daily','transfers','adjustments'],true))$f['platform']='';return $f;
}
function report_products($f){$rows=db()->query('SELECT * FROM products ORDER BY name,id')->fetchAll();return array_values(array_filter($rows,function($p)use($f){return (($f['report']??'')!=='product_master'||($f['product_status']??'all')==='all'||(int)$p['active']===(($f['product_status']??'')==='active'?1:0))&&(!$f['product_id']||(int)$p['id']===$f['product_id'])&&(!$f['brand']||inventory_filter_brand($p['brand'])===$f['brand'])&&(!$f['main_category']||$p['main_category']===$f['main_category'])&&(!$f['subcategory']||$p['category']===$f['subcategory'])&&(!$f['q']||str_contains(norm($p['name'].' '.$p['master_sku'].' '.$p['brand']),norm($f['q'])));}));}
/** Beginning balances predate movements unless a dated beginning import exists. */
function inventory_ledger($pid){
 $pid=(int)$pid;$events=[];$b=db()->prepare('SELECT * FROM beginning_balances WHERE product_id=?');$b->execute([$pid]);if($r=$b->fetch())$events[]=['date'=>substr($r['updated_at'],0,10),'time'=>$r['updated_at'],'type'=>'Beginning Balance','ref'=>'Beginning Balance','platform'=>'','sellable'=>(int)$r['qty'],'restricted'=>0,'physical'=>(int)$r['qty'],'source'=>'beginning','source_id'=>$r['id'],'actor'=>$r['updated_by'],'remarks'=>'Beginning balance uses its recorded update date. Earlier overwritten balances cannot be reconstructed.'];
 foreach(['inflows','outflows','non_sellable','nonsellable_outflows'] as $t){$q=db()->prepare("SELECT * FROM $t WHERE product_id=? ORDER BY id");$q->execute([$pid]);foreach($q as $r){$qty=(int)$r['qty'];$sell=0;$ns=0;if($t==='inflows'){$sell=$qty;$type='Inflow · '.$r['type'];$ref=$r['reference_no'];$pl=$r['source_platform']??'';}
 elseif($t==='outflows'){$sell=-$qty;$type='Outflow · '.$r['type'];$ref=$r['order_id'];$pl=$r['platform'];}
 elseif($t==='non_sellable'){$ns=$qty;$sell=$r['sellable_deducted']?-$qty:0;$type='Restricted · '.$r['condition_type'].' · '.$r['action_type'];$ref=$r['order_id'];$pl=$r['platform'];}
 else{$ns=-$qty;$type='Restricted release · '.$r['type'];$ref=$r['reference_no'];$pl='';}
 $events[]=['date'=>$r['txn_date']?:substr($r['created_at'],0,10),'time'=>$r['created_at'],'type'=>$type,'ref'=>$ref??'','platform'=>$pl??'','sellable'=>$sell,'restricted'=>$ns,'physical'=>$sell+$ns,'source'=>$t,'source_id'=>$r['id'],'actor'=>$r['user_id'],'remarks'=>$r['remarks']??''];}}
 $q=db()->prepare('SELECT * FROM platform_transfers WHERE product_id=?');$q->execute([$pid]);foreach($q as $r)$events[]=['date'=>$r['txn_date'],'time'=>$r['created_at'],'type'=>'Platform Transfer','ref'=>$r['transfer_ref'],'platform'=>$r['from_platform'].' → '.$r['to_platform'],'sellable'=>0,'restricted'=>0,'physical'=>0,'source'=>'transfers','source_id'=>$r['id'],'actor'=>$r['user_id'],'remarks'=>$r['qty'].' pcs; '.$r['reason']];
 if(adjustments_ready()){$q=db()->prepare("SELECT m.*,b.batch_ref FROM adjustment_movements m JOIN inventory_count_batches b ON b.id=m.batch_id WHERE product_id=? AND movement_type='Platform Redistribution'");$q->execute([$pid]);foreach($q as $r)$events[]=['date'=>$r['txn_date'],'time'=>$r['created_at'],'type'=>'Platform Redistribution','ref'=>$r['batch_ref'],'platform'=>'All','sellable'=>0,'restricted'=>0,'physical'=>0,'source'=>'inventory_count','source_id'=>$r['batch_id'],'actor'=>$r['user_id'],'remarks'=>$r['platform_json']];}
 usort($events,fn($a,$b)=>[$a['date'],$a['time'],$a['source'],$a['source_id']]<=>[$b['date'],$b['time'],$b['source'],$b['source_id']]);return $events;
}
function inventory_balance_at($pid,$date){$s=['sellable'=>0,'restricted'=>0,'physical'=>0];foreach(inventory_ledger($pid) as $e)if($e['date']<=$date)foreach($s as $k=>$v)$s[$k]+=$e[$k];return $s;}
function inventory_condition_balances($pid,$date=null){
 $date=$date??date('Y-m-d');$totals=['good'=>inventory_balance_at($pid,$date)['sellable'],'packaging'=>0,'damaged'=>0,'other'=>0];$q=db()->prepare('SELECT condition_type,SUM(qty) qty FROM non_sellable WHERE product_id=? AND txn_date<=? GROUP BY condition_type');$q->execute([$pid,$date]);foreach($q as $r){$kind=packaging_kind($r['condition_type']);$totals[$kind==='packaging'?'packaging':($kind==='damaged'?'damaged':'other')]+=(int)$r['qty'];}
 $q=db()->prepare('SELECT n.condition_type,SUM(l.qty) qty FROM nonsellable_release_links l JOIN nonsellable_outflows o ON o.id=l.release_id JOIN non_sellable n ON n.id=l.non_sellable_id WHERE o.product_id=? AND o.txn_date<=? GROUP BY n.condition_type');$q->execute([$pid,$date]);$linked=0;foreach($q as $r){$kind=packaging_kind($r['condition_type']);$totals[$kind==='packaging'?'packaging':($kind==='damaged'?'damaged':'other')]-=(int)$r['qty'];$linked+=(int)$r['qty'];}
 $q=db()->prepare('SELECT COALESCE(SUM(qty),0) FROM nonsellable_outflows WHERE product_id=? AND txn_date<=?');$q->execute([$pid,$date]);$unlinked=(int)$q->fetchColumn()-$linked;
 // Older count releases had no condition links and treated restricted stock as damaged.
 if($unlinked){foreach(['damaged','other','packaging'] as $k){$take=$unlinked<0?$unlinked:min(max(0,$totals[$k]),$unlinked);$totals[$k]-=$take;$unlinked-=$take;if(!$unlinked)break;}if($unlinked)$totals['other']-=$unlinked;}
 return $totals;
}
function report_stock_event_type($e){$action=$e['action_type'];if(str_contains($action,'Redistribution'))return 'Platform Redistribution';if(str_contains($action,'Physical Adjustment'))return 'Physical Adjustment · Inventory Count Adjustment';if($e['reference_no']==='Beginning Balance')return 'Beginning Balance';$q=db()->prepare('SELECT type FROM inflows WHERE product_id=? AND reference_no=? LIMIT 1');$q->execute([$e['product_id'],$e['reference_no']]);if($t=$q->fetchColumn())return 'Inflow · '.$t;$q=db()->prepare('SELECT type FROM outflows WHERE product_id=? AND order_id=? LIMIT 1');$q->execute([$e['product_id'],$e['reference_no']]);if($t=$q->fetchColumn())return 'Outflow · '.$t;$q=db()->prepare('SELECT id FROM platform_transfers WHERE product_id=? AND transfer_ref=? LIMIT 1');$q->execute([$e['product_id'],$e['reference_no']]);if($q->fetchColumn())return 'Platform Transfer';return $action;}
function report_platform_balance($pid,$platform,$date){$q=db()->prepare('SELECT COALESCE(SUM(after_qty-before_qty),0) FROM stock_events WHERE product_id=? AND platform=? AND txn_date>?');$q->execute([$pid,$platform,$date]);return platform_qty($platform,$pid)-(int)$q->fetchColumn();}
function report_catalog(){return [
 'Overview'=>['overview'=>'Inventory Operations Summary'],
 'Stock Balances'=>['product_master'=>'Product Master / Item Codes','stocks'=>'Inventory Stock Summary','platforms'=>'Platform Inventory','restricted'=>'Restricted Stocks'],
 'Stock Movements'=>['movement'=>'Product Movement History','daily'=>'Daily Inventory Movement','transfers'=>'Stock Transfer & Redistribution','closing'=>'Daily Closing Records'],
 'Transactions'=>['inflow'=>'Inflow Report','outflow'=>'Outflow Report','returns'=>'Returns Report','borrowed'=>'Borrowed Items Report'],
 'Counts & Adjustments'=>['adjustments'=>'Inventory Count & Adjustment','reversals'=>'Linked Reversals'],
 'Exceptions & Audit'=>['negative'=>'Negative Stock Events','uploads'=>'Upload Issues & Duplicates','audit'=>'Audit Trail']];}
function report_titles(){return array_merge(...array_values(report_catalog()));}
function report_source_url($e,$pid){$q=db()->prepare('SELECT id FROM inventory_count_batches WHERE batch_ref=?');$q->execute([$e['ref']]);if($id=$q->fetchColumn())return 'index.php?page=inventory_count&id='.$id;if($e['source']==='inflows'){$q=db()->prepare('SELECT batch_id FROM inflows WHERE id=?');$q->execute([$e['source_id']]);if($id=$q->fetchColumn())return 'index.php?page=inflow_batch&id='.$id;}if($e['source']==='outflows'){$q=db()->prepare('SELECT import_batch_id FROM outflows WHERE id=?');$q->execute([$e['source_id']]);if($id=$q->fetchColumn())return 'index.php?page=outflow_batch&id='.$id;}if($e['source']==='non_sellable')return 'index.php?page=nonsellable';if($e['source']==='nonsellable_outflows')return 'index.php?page=nonsellable_release_detail&id='.(int)$e['source_id'];switch($e['source']){case 'inventory_count':return 'index.php?page=inventory_count&id='.(int)$e['source_id'];case 'transfers':return 'download.php?type=transfer_receipt&id='.(int)$e['source_id'];default:return 'index.php?page=product_detail&id='.(int)$pid.'&from='.rawurlencode($e['date']).'&to='.rawurlencode($e['date']);}}
function inventory_report_build($input){return process_transaction(function()use($input){return inventory_report_build_data($input);});}
function inventory_report_build_data($input){
 $f=report_filters($input);$key=$f['report']?:'overview';$titles=report_titles();if(!isset($titles[$key]))throw new Exception('Unknown report.');$products=report_products($f);$rows=[];$links=[];$summary=[];$heads=[];$prior=date('Y-m-d',strtotime($f['from'].' -1 day'));$users=[];foreach(db()->query('SELECT id,name FROM users') as $u)$users[$u['id']]=$u['name'];$allowed=array_column($products,'id');$pm=array_column($products,null,'id');
 $add=function($row,$url='')use(&$rows,&$links){$rows[]=$row;$links[]=$url;};
 $notes=['Transaction-date basis; quantities in pieces. Posted ledger entries and linked inverse reversals are retained.','Historical beginning balance uses its saved update date. Earlier overwritten beginning balances are unavailable.'];
 if($key==='product_master'){$heads=['Master SKU','Product Description','Brand','Main Category','Subcategory','Variant','Status'];foreach($products as $p)$add([$p['master_sku'],$p['name'],inventory_filter_brand($p['brand']),$p['main_category'],$p['category'],$p['variant'],(int)$p['active']?'Active':'Inactive'],'index.php?page=product_detail&id='.$p['id']);$notes=['Current product identities; dates do not filter this master list. Item codes are retained during normal category edits. When Brand SKU Format is enabled, a brand correction updates the brand prefix and retains the previous code as an alias.'];}
 elseif(in_array($key,['overview','stocks','restricted','platforms'],true)){
  $heads=$key==='overview'?['Master SKU','Product','Opening Sellable','Inflow','Outflow / Condition Out','Net Adjustment','Closing Sellable','Closing Restricted','Closing Physical']:($key==='stocks'?['Master SKU','Product','Sellable','RAW / Packaging','Damaged / Leak','Other Restricted','Physical Total']:($key==='platforms'?['Master SKU','Product','Lazada','Shopee','TikTok','Platform Total','Sellable','Alignment Difference']:['Master SKU','Product','Record','Condition','Remaining','Received','Days Pending','Due Date','Responsible','Reference']));
  foreach($products as $p){$pid=$p['id'];$open=inventory_balance_at($pid,$prior);$close=inventory_balance_at($pid,$f['to']);
   if($key==='overview'){$in=0;$out=0;$adj=0;foreach(inventory_ledger($pid) as $e)if($e['date']>=$f['from']&&$e['date']<=$f['to']){if(str_contains($e['type'],'Inventory Count Adjustment'))$adj+=$e['sellable'];elseif($e['sellable']>=0)$in+=$e['sellable'];else $out-=$e['sellable'];}$add([$p['master_sku'],$p['name'],$open['sellable'],$in,$out,$adj,$close['sellable'],$close['restricted'],$close['physical']],'index.php?page=product_detail&id='.$pid);foreach(['Opening'=>$open['sellable'],'Inflow'=>$in,'Outflow / Condition Out'=>$out,'Net Adjustment'=>$adj,'Closing Sellable'=>$close['sellable'],'Closing Restricted'=>$close['restricted']] as $k=>$v)$summary[$k]=($summary[$k]??0)+$v;}
   elseif($key==='stocks'){$c=inventory_condition_balances($pid,$f['to']);$add([$p['master_sku'],$p['name'],$close['sellable'],$c['packaging'],$c['damaged'],$c['other'],$close['physical']],'index.php?page=product_detail&id='.$pid);}
   elseif($key==='platforms'){$qs=[];foreach(['Lazada','Shopee','TikTok'] as $pl)$qs[]=report_platform_balance($pid,$pl,$f['to']);if($f['platform']){$ix=array_search($f['platform'],['Lazada','Shopee','TikTok'],true);$heads=['Master SKU','Product','Platform','Platform Qty'];$add([$p['master_sku'],$p['name'],$f['platform'],$qs[$ix]]);}else $add([$p['master_sku'],$p['name'],...$qs,array_sum($qs),$close['sellable'],$close['sellable']-array_sum($qs)]);}
   else{$q=db()->prepare('SELECT n.*,COALESCE((SELECT SUM(l.qty) FROM nonsellable_release_links l JOIN nonsellable_outflows o ON o.id=l.release_id WHERE l.non_sellable_id=n.id AND o.txn_date<=?),0) released FROM non_sellable n WHERE product_id=? AND txn_date<=? AND qty>0');$q->execute([$f['to'],$pid,$f['to']]);foreach($q as $n){$reversalDate=null;if($n['reversed_by_request']){$v=db()->prepare("SELECT DATE(approved_at) FROM transaction_reversals WHERE id=? AND status='Approved'");$v->execute([$n['reversed_by_request']]);$reversalDate=$v->fetchColumn();}if($reversalDate&&$reversalDate<=$f['to'])continue;$left=(int)$n['qty']-(int)$n['released'];if($left<=0)continue;$add([$p['master_sku'],$p['name'],'NS-'.$n['id'],$n['condition_type'],$left,$n['txn_date'],(int)((strtotime($f['to'])-strtotime($n['txn_date']))/86400),$n['packaging_due_date']??'',$users[$n['packaging_owner_id']??0]??'',$n['order_id']],'index.php?page=nonsellable');}}}
  if($key==='platforms')$notes[]='Historical platform balances are reconstructed from current allocations and dated stock events. Quantities preceding platform-event tracking use the legacy opening allocation.';
  if($key==='restricted')$notes[]='Source-record view. Legacy unlinked restricted releases may leave individual-source availability unverified; reconcile against Stock Summary totals.';
 }elseif(in_array($key,['movement','daily','inflow','outflow','transfers'],true)){
  $heads=$key==='daily'?['Date','Master SKU','Product','Opening Sellable','In','Out','Net Adjustment','Closing Sellable','Closing Restricted','Closing Physical']:['Date','Master SKU','Product','Movement','Reference','Platform','Sellable Change','Restricted Change','Physical Change','Sellable Balance','Physical Balance','Processed By','Recorded At','Remarks'];
  foreach($products as $p){$pid=$p['id'];$ev=inventory_ledger($pid);$balance=inventory_balance_at($pid,$prior);
   if($key==='daily'){if((strtotime($f['to'])-strtotime($f['from']))/86400>366)throw new Exception('Limit daily reports to 366 days.');for($d=$f['from'];$d<=$f['to'];$d=date('Y-m-d',strtotime($d.' +1 day'))){$op=$balance['sellable'];$in=0;$out=0;$adj=0;foreach($ev as $e)if($e['date']===$d){foreach($balance as $k=>$v)$balance[$k]+=$e[$k];if(str_contains($e['type'],'Inventory Count Adjustment'))$adj+=$e['sellable'];elseif($e['sellable']>=0)$in+=$e['sellable'];else $out-=$e['sellable'];}$add([$d,$p['master_sku'],$p['name'],$op,$in,$out,$adj,$balance['sellable'],$balance['restricted'],$balance['physical']]);}continue;}
   if($f['platform']&&$key==='movement'){$heads=['Date','Master SKU','Product','Platform Movement','Reference','Platform','Change','Platform Balance','Processed By','Recorded At'];$run=report_platform_balance($pid,$f['platform'],$prior);$add([$prior,$p['master_sku'],$p['name'],'Opening Balance','Before selected period',$f['platform'],0,$run,'','']);$q=db()->prepare('SELECT * FROM stock_events WHERE product_id=? AND platform=? AND txn_date BETWEEN ? AND ? ORDER BY txn_date,created_at,id');$q->execute([$pid,$f['platform'],$f['from'],$f['to']]);foreach($q as $e){$e['action_type']=report_stock_event_type($e);$delta=(int)$e['after_qty']-(int)$e['before_qty'];$run+=$delta;if($f['reference']&&!str_contains(norm($e['reference_no']),norm($f['reference'])))continue;if($f['movement']&&!str_contains(norm($e['action_type']),norm($f['movement'])))continue;$add([$e['txn_date'],$p['master_sku'],$p['name'],$e['action_type'],$e['reference_no'],$e['platform'],$delta,$run,$users[$e['user_id']]??'',$e['created_at']]);}$add([$f['to'],$p['master_sku'],$p['name'],'Closing Balance','All platform movements included',$f['platform'],0,$run,'','']);continue;}
   if($key==='movement')$add([$prior,$p['master_sku'],$p['name'],'Opening Balance','Before selected period','',0,0,0,$balance['sellable'],$balance['physical'],'','','']);
   foreach($ev as $e){if($e['date']<$f['from']||$e['date']>$f['to'])continue;foreach($balance as $k=>$v)$balance[$k]+=$e[$k];if($key==='inflow'&&$e['source']!=='inflows'&& !($e['source']==='non_sellable'&&!$e['sellable']))continue;if($key==='outflow'&&!in_array($e['source'],['outflows','nonsellable_outflows'],true))continue;if($key==='transfers'&&!in_array($e['type'],['Platform Transfer','Platform Redistribution'],true))continue;if($f['platform']&&$e['platform']!==$f['platform'])continue;if($f['reference']&&!str_contains(norm($e['ref']),norm($f['reference'])))continue;if($f['movement']&&!str_contains(norm($e['type']),norm($f['movement'])))continue;$add([$e['date'],$p['master_sku'],$p['name'],$e['type'],$e['ref'],$e['platform'],$e['sellable'],$e['restricted'],$e['physical'],$balance['sellable'],$balance['physical'],$users[$e['actor']]??'',$e['time'],$e['remarks']],report_source_url($e,$pid));$summary['Filtered Sellable Change']=($summary['Filtered Sellable Change']??0)+$e['sellable'];$summary['Filtered Physical Change']=($summary['Filtered Physical Change']??0)+$e['physical'];}
   if($key==='movement')$add([$f['to'],$p['master_sku'],$p['name'],'Closing Balance','All movements included','',0,0,0,$balance['sellable'],$balance['physical'],'','','']);
  }$notes[]='Running balances include all movements, including rows hidden by movement-type filters. Filtered movement totals are not the complete period roll-forward.';
 }elseif($key==='returns'){$heads=['Date','Transaction Type','Master SKU','Product','Order ID','Platform','Good','Damaged','For Repackaging','Total','Status','Processed By'];foreach(db()->query('SELECT r.*,b.batch_ref FROM posted_returns r JOIN return_batches b ON b.id=r.batch_id ORDER BY r.txn_date,r.id') as $r){if(!in_array($r['product_id'],$allowed)||$r['txn_date']<$f['from']||$r['txn_date']>$f['to']||($f['platform']&&$r['platform']!==$f['platform']))continue;$p=$pm[$r['product_id']];$add([$r['txn_date'],str_starts_with($r['batch_ref'],'CAN-')?'Cancelled Order':'Return Order',$p['master_sku'],$p['name'],$r['original_ref'],$r['platform'],(int)$r['good_qty'],(int)$r['damaged_qty'],(int)$r['repackaging_qty'],(int)$r['qty'],$r['reversed']?'Reversed':'Posted',$users[$r['user_id']]??''],'index.php?page=order_return&id='.$r['batch_id']);}
 }elseif($key==='borrowed'){$heads=['Borrow Ref','Master SKU','Product','Borrower','Platform','Issued','Returned','Converted','Outstanding','Issue Date','Due Date','Status'];foreach(db()->query('SELECT * FROM borrowed_items ORDER BY id DESC') as $r){if(!in_array($r['product_id'],$allowed)||$r['issue_date']<$f['from']||$r['issue_date']>$f['to']||($f['platform']&&$r['source_platform']!==$f['platform']))continue;$p=$pm[$r['product_id']];$add([$r['borrow_ref'],$p['master_sku'],$p['name'],$r['borrower'],$r['source_platform'],(int)$r['qty'],(int)$r['returned_qty'],(int)$r['converted_qty'],(int)$r['qty']-(int)$r['returned_qty']-(int)$r['converted_qty'],$r['issue_date'],$r['due_date'],$r['status']],'index.php?page=borrowed');}$notes[]='Borrow issue dates are filtered; returned/outstanding values are current operational totals, not a historical as-of reconstruction.';
 }elseif($key==='adjustments'){$heads=['Reference','Count Date','Master SKU','Product','Snapshot Physical','First Count','Final Verified','Variance','Status','Reason','Supporting Reference','Reviewer','Approver','Rule & Rounding','Posting Breakdown'];$q=db()->query('SELECT b.*,l.master_sku,l.product_id,l.product_name,l.on_hand,l.actual_count,l.final_conditions,l.posting_json FROM inventory_count_batches b JOIN inventory_count_lines l ON l.batch_id=b.id ORDER BY b.id DESC,l.id');foreach($q as $r){$d=$r['count_date'];if($d<$f['from']||$d>$f['to']||!in_array($r['product_id'],$allowed))continue;$fc=json_decode($r['final_conditions']??'null',true);$final=is_array($fc)?array_sum($fc):$r['actual_count'];$add([$r['batch_ref'],$d,$r['master_sku'],$r['product_name'],(int)$r['on_hand'],$r['actual_count']===null?'':(int)$r['actual_count'],$final===null?'':(int)$final,$final===null?'':(int)$final-(int)$r['on_hand'],$r['status'],$r['reason'],$r['support_reference'],$r['reviewed_name'],$r['approved_name'],$r['rule_json'],$r['posting_json']],'index.php?page=inventory_count&id='.$r['id']);}
 }elseif($key==='closing'){$heads=['Cutoff Date','Version','Event','Master SKU','Product','Opening Sellable','In','Out','Net Adjustment','Closing Sellable','Closing Restricted','Closing Physical','Recorded At','Admin','Reason'];foreach(db()->query('SELECT * FROM daily_closing_versions ORDER BY close_date DESC,version DESC') as $r)if($r['close_date']>=$f['from']&&$r['close_date']<=$f['to']){$detail=json_decode($r['details_json'],true);foreach($detail['rows']??[] as $line)$add([$r['close_date'],(int)$r['version'],$r['event_type'],...array_slice($line,1),$r['created_at'],$users[$r['user_id']]??'',$r['reason']],'index.php?page=day_closing&close_date='.$r['close_date']);}$notes[]='Permanent versions are recorded when Admin closes/reopens a day. Daily Movement separately calculates each date, including dates without a formal closing.';
 }elseif($key==='negative'){$heads=['Date','Master SKU','Product','Platform','Before','After','Reference','Status','Opened By','Reason','Correction Reference'];foreach(db()->query('SELECT * FROM stock_exceptions ORDER BY id DESC') as $r)if(in_array($r['product_id'],$allowed)&&$r['txn_date']>=$f['from']&&$r['txn_date']<=$f['to']&&(!$f['platform']||$r['platform']===$f['platform'])){$p=$pm[$r['product_id']];$add([$r['txn_date'],$p['master_sku'],$p['name'],$r['platform'],(int)$r['before_qty'],(int)$r['after_qty'],$r['reference_no'],$r['status'],$users[$r['opened_by']]??'',$r['reason'],$r['correction_reference']],'index.php?page=stock_exceptions');}
 }elseif($key==='reversals'){$heads=['Reversal','Source Type','Source ID','Status','Reason','Requested By','Approved By','Requested At','Approved At'];foreach(db()->query('SELECT * FROM transaction_reversals ORDER BY id DESC') as $r)if(substr($r['created_at'],0,10)>=$f['from']&&substr($r['created_at'],0,10)<=$f['to'])$add(['REV-'.$r['id'],$r['source_type'],$r['source_id'],$r['status'],$r['reason'],$users[$r['requested_by']]??'',$users[$r['approved_by']]??'',$r['created_at'],$r['approved_at']],'index.php?page=corrections');
 }elseif($key==='uploads'){$heads=['Recorded At','Type','Reference','Platform','Filename','Status','Errors','Duplicates','Error Details'];foreach(db()->query('SELECT * FROM import_batches ORDER BY id DESC') as $r)if(substr($r['created_at'],0,10)>=$f['from']&&substr($r['created_at'],0,10)<=$f['to']&&(!$f['platform']||$f['platform']===$r['platform']))$add([$r['created_at'],$r['import_type'],'IMPORT-'.$r['id'],$r['platform'],$r['filename'],$r['status'],(int)$r['error_count'],(int)$r['duplicate_count'],$r['error_json']],'index.php?page=imports&history=all');foreach(db()->query('SELECT * FROM inflow_batches ORDER BY id DESC') as $r)if(substr($r['created_at'],0,10)>=$f['from']&&substr($r['created_at'],0,10)<=$f['to']&&!$f['platform'])$add([$r['created_at'],'Inflow',$r['batch_ref'],'',$r['original_filename'],$r['status'],(int)$r['error_count'],'See details',$r['error_json']],'index.php?page=inflow_batch&id='.$r['id']);
 }else{$heads=['Recorded At','Action','Entity','Reference','Details','Processed By'];foreach(db()->query('SELECT * FROM activity_log ORDER BY id DESC') as $r)if(substr($r['created_at'],0,10)>=$f['from']&&substr($r['created_at'],0,10)<=$f['to']&&(!$f['q']||str_contains(norm(implode(' ',array_map(fn($v)=>(string)$v,$r))),norm($f['q']))))$add([$r['created_at'],$r['action_type'],$r['entity_type'],$r['entity_ref'],$r['details'],$users[$r['user_id']]??''],'index.php?page=activity');}
 if(count($rows)>100000)throw new Exception('Report exceeds 100,000 rows. Narrow the dates/products.');
 return ['title'=>$titles[$key],'headers'=>$heads,'rows'=>$rows,'links'=>$links,'summary'=>$summary,'filters'=>$f,'notes'=>$notes,'generated'=>date('Y-m-d H:i:s'),'user'=>current_user()['name']];
}
function report_meta($r){return ['Period'=>$r['filters']['from'].' to '.$r['filters']['to'],'Filters'=>json_encode($r['filters'],JSON_UNESCAPED_UNICODE),'Generated'=>$r['generated'],'Generated By'=>$r['user'],'Summary'=>$r['summary']?json_encode($r['summary']):'See report rows','Notes'=>implode(' ',$r['notes'])];}
function daily_closing_archive($date,$event,$reason){if(!adjustments_ready())return;$q=db()->prepare('SELECT COALESCE(MAX(version),0)+1 FROM daily_closing_versions WHERE close_date=?');$q->execute([$date]);$v=(int)$q->fetchColumn();$r=inventory_report_build(['report'=>'daily','from'=>$date,'to'=>$date]);db()->prepare('INSERT INTO daily_closing_versions(close_date,version,event_type,details_json,reason,user_id) VALUES(?,?,?,?,?,?)')->execute([$date,$v,$event,json_encode(['headers'=>$r['headers'],'rows'=>$r['rows'],'generated'=>$r['generated']]),$reason,current_user()['id']]);}
